function R=CHECK_TRAJECTORY_C9_13D_SHARED_KERNEL_AB()
% Temporary diagnostic, common_matlab/ root; generated files live HERE.
% Benchmarks four ALGEBRAICALLY EQUIVALENT local-search models:
%     1 old repeated duration derivatives + scalar dual-jet evaluation
%     2 one validated duration derivative shared across body and torque
%     3 repeated derivative data + batched Bernstein point jets
%     4 shared derivative data + batched Bernstein point jets
% No sampled value certifies continuous time or actual HLC.
root=fileparts(mfilename('fullpath'));
name='TRAJECTORY_C9_13D_SHARED_KERNEL_AB_RESULT';
R=struct('status','FAIL_NOT_STARTED','stage','INIT','error_message','', ...
    'error_identifier','','error_stack',{{}},'safe_to_commit',false, ...
    'mode_names',{{'BASELINE','SHARED_ONLY','BATCH_ONLY','SHARED_AND_BATCH'}}, ...
    'model_median_ms',NaN(1,4),'model_p95_ms',NaN(1,4), ...
    'model_max_ms',NaN(1,4),'gradient_median_ms',NaN(1,4), ...
    'metric_max_abs_difference',NaN,'constraint_A_max_rel',NaN, ...
    'constraint_b_max_rel',NaN,'torque_value_max_rel',NaN, ...
    'torque_jacobian_max_rel',NaN,'duration_cache_bad_phase_rejected',false, ...
    'duration_cache_single_phase_accepted',false, ...
    'mode_qp_ready',false(1,4), ...
    'nominal_all_time_proven',false,'actual_HLC_tracking_proven',false, ...
    'zip_path',fullfile(root,[name '_FOR_CHATGPT.zip']));
try
    addpath(fullfile(root,'reference','REPLANNING_SYSTEM', ...
        'TRAJECTORY_GENERATION'),'-begin');
    addpath(fullfile(root,'reference','REPLANNING_SYSTEM', ...
        'OBSTACLE_INFORMATION'),'-begin');
    R.stage='CONSTRUCT_13D_PHYSICAL_PARAMETER_FIXTURE';
    t0=4;T=6;
    left=zeros(3,10);right=zeros(3,10);
    left(:,1)=[0;0;5];right(:,1)=[6;1.2;5];
    left(:,2)=[1;0.2;0];right(:,2)=[1;0.2;0];
    k=10:13;
    free=[6*k/23;1.2*k/23+[.04 -.06 .05 -.03]; ...
        [5.015 4.980 5.010 5.000]];
    authority=struct('gravity_world_mps2',[0;0;-9.80665], ...
        'cable_length_m',2,'uav_mass_kg',1.5, ...
        'payload_mass_kg',0.18,'uav_inertia_kgm2',[.02;.03;.04], ...
        'torque_limits_Nm',[-1 1;-1 1;-1 1]);
    opts=struct('minimum_force_z_N',0,'minimum_planar_speed_mps',0, ...
        'torque_guard_Nm',zeros(3,1),'use_vectorized_bernstein_point_jets',true);
    obs1=struct('id',1,'type','sphere','dimensions',.35, ...
        'center0',[3;.6;5],'is_stationary',true,'rotation',eye(3));
    obs2=struct('id',2,'type','ellipsoid', ...
        'dimensions',[.45 .25 .65], ...
        'center0',[4;.4;5.2],'is_stationary',true,'rotation',eye(3));
    shapes=TRAJECTORY_OBSTACLE_SUPPORT.prepare([obs1 obs2]);
    phases=[0 .17 .31 .57 .83 1];
    req=struct('t0_s',t0,'duration_s',T, ...
        'start_jets',left,'end_jets',right,'nominal_free',free, ...
        'authority',authority,'flight_interval_s',[t0-2,t0+15], ...
        'geometry_options',struct('numerical_guard_m',0, ...
             'robust_tube_enabled',0,'trajectory_phase','f'), ...
        'search_options',struct('min_separation_m',.01, ...
             'use_shared_13d_duration_cache',0), ...
        'torque_options',opts);
    rad=[.12 .01 .15];
    R.stage='MATHEMATICAL_QP_ROW_PARITY';
    base=[];
    R.metric_max_abs_difference=0;
    R.constraint_A_max_rel=0;
    R.constraint_b_max_rel=0;
    for mode=1:4
        x=req;
        x.search_options.use_shared_13d_duration_cache=double(mode==2||mode==4);
        x.torque_options.use_batched_13d_torque_jets=double(mode==3||mode==4);
        Q=TRAJECTORY_C9_13D_NATURAL_QP(x,shapes,phases,rad,true);
        R.mode_qp_ready(mode)=Q.solved;
        assert(Q.solved,'C9_13D_AB:QPNotReady',Q.status);
        if mode==1,base=Q;continue;end
        R.metric_max_abs_difference=max(R.metric_max_abs_difference, ...
            max(abs(Q.H-base.H),[],'all'));
        R.constraint_A_max_rel=max(R.constraint_A_max_rel, ...
            max(abs(Q.raw_A-base.raw_A),[],'all')/ ...
            max(1,max(abs(base.raw_A),[],'all')));
        R.constraint_b_max_rel=max(R.constraint_b_max_rel, ...
            max(abs(Q.raw_b-base.raw_b),[],'all')/ ...
            max(1,max(abs(base.raw_b),[],'all')));
        assert(isequal(size(base.raw_A),size(Q.raw_A))&& ...
            isequal(size(base.raw_b),size(Q.raw_b)), ...
            'C9_13D_AB:ConstraintSize','Constraint sizes changed.');
    end
    assert(R.metric_max_abs_difference<1e-9&& ...
        R.constraint_A_max_rel<1e-8&& ...
        R.constraint_b_max_rel<1e-8, ...
        'C9_13D_AB:QPConstraintParity','A 13D local QP matrix changed.');
    R.torque_value_max_rel=0;R.torque_jacobian_max_rel=0;
    R.stage='ALL_THREE_AXIS_13D_TORQUE_POINT_PARITY';
    piece=TRAJECTORY_C9_FLAT_BERNSTEIN.build(t0,T,left,right,free);
    S=TRAJECTORY_C9_DURATION_SENSITIVITY(t0,T,left,right,free,phases);
    Z0=TRAJECTORY_C9_TORQUE_FORWARD_JACOBIAN_13D( ...
        piece,authority,opts,phases);
    assert(all(Z0.valid),'C9_13D_AB:PointDegenerate',Z0.status);
    for mode=2:4
        o=opts;
        o.use_batched_13d_torque_jets=double(mode==3||mode==4);
        if mode==2||mode==4
            Z=TRAJECTORY_C9_TORQUE_FORWARD_JACOBIAN_13D( ...
                piece,authority,o,phases,S);
        else
            Z=TRAJECTORY_C9_TORQUE_FORWARD_JACOBIAN_13D( ...
                piece,authority,o,phases);
        end
        assert(all(Z.valid),'C9_13D_AB:PointDegenerate',Z.status);
        R.torque_value_max_rel=max([0,R.torque_value_max_rel, ...
            max(abs(Z0.torque_Nm-Z.torque_Nm),[],'all')/ ...
            max(1,max(abs(Z0.torque_Nm),[],'all'))],[],'omitnan');
        R.torque_jacobian_max_rel=max([0,R.torque_jacobian_max_rel, ...
            max(abs(Z0.gradient_Nm_per_physical-Z.gradient_Nm_per_physical), ...
                [],'all')/ ...
            max(1,max(abs(Z0.gradient_Nm_per_physical),[],'all'))],[],'omitnan');
    end
    assert(R.torque_value_max_rel<1e-8&& ...
        R.torque_jacobian_max_rel<1e-8, ...
        'C9_13D_AB:TorqueParity','13D torque or sensitivity changed.');
    R.stage='CROSS_CANDIDATE_CACHE_MUST_FAIL_CLOSED';
    bad=S;bad.phase_samples(2)=.123;
    try
        TRAJECTORY_C9_DURATION_FULLBODY_JACOBIAN(t0,T,left,right, ...
            free,phases,authority.gravity_world_mps2, ...
            authority.cable_length_m,bad);
    catch ME
        R.duration_cache_bad_phase_rejected= ...
            strcmp(ME.identifier,'C9_DURATION_FULLBODY:StaleDurationCache');
    end
    assert(R.duration_cache_bad_phase_rejected, ...
        'C9_13D_AB:StaleCache','Stale phase data were accepted.');
    single=.31;
    one=TRAJECTORY_C9_DURATION_SENSITIVITY(t0,T,left,right,free,single);
    F=TRAJECTORY_C9_DURATION_FULLBODY_JACOBIAN(t0,T,left,right, ...
        free,single,authority.gravity_world_mps2, ...
        authority.cable_length_m,one);
    R.duration_cache_single_phase_accepted= ...
        strcmp(F.status,'VALID_LOCAL_13D_TANGENT__INDEPENDENT_FULL_TIME_PROOF_REQUIRED');
    assert(R.duration_cache_single_phase_accepted, ...
        'C9_13D_AB:SinglePhase','A valid one-phase cache was rejected.');
    R.stage='REPEATED_AB_TIMING';
    samples=zeros(7,4);grad=zeros(7,4);
    for rep=1:7
        for ix=1:4
            mode=mod(ix+rep-2,4)+1;
            x=req;
            x.search_options.use_shared_13d_duration_cache=double(mode==2||mode==4);
            x.torque_options.use_batched_13d_torque_jets=double(mode==3||mode==4);
            clock=tic;
            Q=TRAJECTORY_C9_13D_NATURAL_QP(x,shapes,phases,rad,true);
            samples(rep,mode)=1000*toc(clock);
            grad(rep,mode)=Q.torque_gradient_ms;
            assert(Q.solved,'C9_13D_AB:Runtime','QP model unavailable on repeated test.');
        end
    end
    R.model_median_ms=median(samples,1);
    R.model_p95_ms=prctile(samples,95,1);
    R.model_max_ms=max(samples,[],1);
    R.gradient_median_ms=median(grad,1);
    R.status='PASS_13D_SHARED_CACHE_AND_BATCH_PARITY__NOT_ALL_TIME_NOT_HLC';
catch ME
    R.status='FAIL_13D_SHARED_KERNEL';
    R.error_message=ME.message;
    R.error_identifier=ME.identifier;
    R.error_stack=arrayfun(@(x)sprintf('%s:%d',x.name,x.line), ...
        ME.stack,'UniformOutput',false);
end
save(fullfile(root,[name '.mat']),'R');
fid=fopen(fullfile(root,[name '.txt']),'w');
if fid>=0
    fprintf(fid,'status=%s stage=%s error=%s %s\n', ...
        R.status,R.stage,R.error_identifier,R.error_message);
    fprintf(fid,'mode_names=%s\n',strjoin(R.mode_names,','));
    fprintf(fid,'model_median_ms=%.9g ',R.model_median_ms);fprintf(fid,'\n');
    fprintf(fid,'model_p95_ms=%.9g ',R.model_p95_ms);fprintf(fid,'\n');
    fprintf(fid,'model_max_ms=%.9g ',R.model_max_ms);fprintf(fid,'\n');
    fprintf(fid,'gradient_median_ms=%.9g ',R.gradient_median_ms);fprintf(fid,'\n');
    fprintf(fid,'H_diff=%.12g A_rel=%.12g b_rel=%.12g\n', ...
        R.metric_max_abs_difference,R.constraint_A_max_rel,R.constraint_b_max_rel);
    fprintf(fid,'torque_rel=%.12g jac_rel=%.12g\n', ...
        R.torque_value_max_rel,R.torque_jacobian_max_rel);
    fprintf(fid,'stale_rejected=%d single_phase_accepted=%d\n', ...
        R.duration_cache_bad_phase_rejected,R.duration_cache_single_phase_accepted);
    for i=1:numel(R.error_stack),fprintf(fid,'stack=%s\n',R.error_stack{i});end
    fprintf(fid,'safe_to_commit=0 actual_HLC_tracking_proven=0\n');
    fclose(fid);
end
zip(R.zip_path,{[name '.mat'],[name '.txt']},root);
fprintf('[C9 13D SHARED KERNEL] %s\n',R.status);
end
